entries[145433] = { ["name"] = "Arcane Charge", ["text"] = "Instant\nAn arcane charge, generated by Arcane Blast, Arcane Missiles, and Arcane Explosion, and consumed by Arcane Barrage and Evocation:\n\nArcane Blast\nGenerates a charge.\nArcane Blast's damage is increased by 50% per charge, and its mana cost increased by 150% per charge.\n\nArcane Missiles\nGenerates a charge.\nArcane Missiles' damage is increased by 50% per charge.\n\nArcane Explosion\nRefreshes charges and has a 30% chance to generate a charge if at least one target is hit.\n\nArcane Barrage\nConsumes all charges.\nArcane Barrage's damage is increased by 50% per charge, and it hits 1 additional nearby target per charge for 50% damage.\n\nEvocation\nConsumes all charges.\nEvocation's mana generation is increased by 25% per charge.\n\nStacks up to 4 times and lasts 10 sec." }
